import sys, random, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
from planner import compile_plan, deficient_cut
from verify_plan import verify_plan

def gen(rnd):
    style = rnd.choice(['sparse','dense','star','ring','twoswitch'])
    n = rnd.randint(3,10)
    links=[]; caps=[]
    allp=[(u,v) for u in range(n) for v in range(u+1,n)]
    if style=='sparse':
        k=rnd.randint(n-1,min(len(allp),2*n))
        sel=rnd.sample(allp,k)
    elif style=='dense':
        sel=allp
    elif style=='star':
        c=rnd.randrange(n); sel=[(min(c,x),max(c,x)) for x in range(n) if x!=c]
    elif style=='ring':
        sel=[(i,(i+1)%n) for i in range(n)]
        sel=[(min(a,b),max(a,b)) for a,b in sel]
    else:
        sel=[(i,j) for i in range(n) for j in range(i+1,n) if rnd.random()<0.5]
        if not sel: sel=[allp[0]]
    links=sel
    caps=[rnd.choice([0,1,2,3,5,10,100,10**6]) for _ in links]
    npart=rnd.randint(2,min(n,6))
    parts=rnd.sample(range(n),npart)
    rdem={v:rnd.choice([0,0,1,2,5,17,10**6,10**12]) for v in parts}
    if sum(rdem.values())==0: rdem[parts[0]]=rnd.randint(1,5)
    return n,links,caps,parts,rdem

def run(seed):
    rnd=random.Random(seed)
    n,links,caps,parts,rdem=gen(rnd)
    period=rnd.choice([1,2,7,1000])
    envelope={i:c for i,c in enumerate(caps) if c>0}
    cpl=[period*envelope.get(i,0) for i in range(len(links))]
    cap={}
    for lid,(u,v) in enumerate(links):
        if cpl[lid]>0:
            cap[(u,v)]=cap.get((u,v),0)+cpl[lid]; cap[(v,u)]=cap.get((v,u),0)+cpl[lid]
    total=sum(rdem.values())
    feas = deficient_cut(n,cap,sorted(parts),rdem,total) is None
    t0=time.time()
    try:
        res=compile_plan(n,links,cpl,parts,rdem)
    except Exception as e:
        print('seed',seed,'EXC',type(e).__name__,e,'feasible',feas)
        print(' n',n,'links',links,'cpl',cpl,'parts',parts,'rdem',rdem)
        return False
    dt=time.time()-t0
    if dt>1.0: print('seed',seed,'SLOW %.2f'%dt)
    if res[0]=='cut':
        if feas:
            print('seed',seed,'DENIED but feasible'); return False
        S=res[1]; Sset=set(S)
        inter=[v for v in S if v in set(parts)]
        assert inter and len(inter)<len(parts)
        tot=sum(cpl[lid] for lid,(u,v) in enumerate(links) if (u in Sset)!=(v in Sset))
        dem=sum(rdem[v] for v in inter)
        if not tot<dem:
            print('seed',seed,'bad witness',tot,dem,S); return False
    else:
        if not feas:
            print('seed',seed,'PLAN but infeasible'); return False
        errs=[]
        if not verify_plan(res[1],links,cpl,period,envelope,parts,rdem,err=lambda m:errs.append(m)):
            print('seed',seed,'INVALID PLAN',errs[:3])
            print(' n',n,'links',links,'cpl',cpl,'parts',parts,'rdem',rdem)
            return False
        if len(res[1]['trees'])>8192 or len(res[1]['routes'])>32768 or len(res[1]['recipes'])>65536:
            print('seed',seed,'SIZE LIMITS',len(res[1]['trees']),len(res[1]['routes']),len(res[1]['recipes'])); return False
    return True

bad=0; t0=time.time()
N=int(sys.argv[1]) if len(sys.argv)>1 else 2000
for seed in range(N):
    if not run(seed):
        bad+=1
        if bad>4: break
print('bad',bad,'time %.1f'%(time.time()-t0))
